def compute(vars):
    book_value = vars["Book Value"]
    goodwill = vars["Goodwill"]
    intangible_assets = vars["Intangible Assets"]
    preferred_equity = vars["Preferred Equity"]

    tangible_common_equity = book_value - (goodwill + intangible_assets + preferred_equity)

    return {
        "value": tangible_common_equity,
        "trace": {
            "Book Value": book_value,
            "Goodwill": goodwill,
            "Intangible Assets": intangible_assets,
            "Preferred Equity": preferred_equity,
            "output_meta": {
                "currency": "dollars",
                "scale": "billion",
                "unit": None
            }
        }
    }
